// Learning Lab app
const SEED=(()=>{const cards=[];for(const[sec,qs]of Object.entries(window.SCRP_BANK||{}))qs.forEach(([q,c,w,e,p])=>cards.push({q,o:[c,...w],a:0,e,t:sec,p}));return{id:'scrp',name:'SCRP Complete Guide',cards}})();
let S={decks:[SEED],cur:'scrp',hist:{}};const save=()=>{};
const deck=()=>S.decks.find(d=>d.id===S.cur)||S.decks[0];
const H=()=>(S.hist[S.cur]??={sessions:[],cardStats:{}});
let view='dash',Q=null,F=null,setup={secs:null,count:'25',mode:'practice'};
const $=s=>document.querySelector(s),app=$('#app');
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const L='ABCDEF';
const sections=()=>{const m=new Map();deck().cards.forEach((c,i)=>{const t=c.t||'General';if(!m.has(t))m.set(t,[]);m.get(t).push(i)});return m};
const pg=c=>c.p?` <span class="muted">(Guide p. ${c.p})</span>`:'';
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.random()*(i+1)|0;[a[i],a[j]]=[a[j],a[i]]}return a}
function renderSel(){$('#deckSel').innerHTML=S.decks.map(d=>`<option value="${d.id}" ${d.id===S.cur?'selected':''}>${esc(d.name)} (${d.cards.length})</option>`).join('')}
$('#deckSel').onchange=e=>{S.cur=e.target.value;setup.secs=null;go(view==='build'?'build':'dash')};
$('#nav').onclick=e=>{if(e.target.dataset.v)go(e.target.dataset.v)};
function nav(v){view=v;document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('on',b.dataset.v===v))}
function go(v){nav(v);renderSel();clearInterval(tmr);({dash,quiz:quizSetup,flash:flashSetup,build,definitions:definitionsPage,scenarios:scenariosPage})[v]();window.scrollTo(0,0)}
function secStat(idx){const cs=H().cardStats;let r=0,w=0,m=0,seen=0;idx.forEach(i=>{const s=cs[i];if(s){r+=s.r;w+=s.w;seen++;if(s.r>=1&&s.r>s.w)m++}});return{r,w,m,seen,acc:r+w?Math.round(r/(r+w)*100):null,mast:idx.length?Math.round(m/idx.length*100):0}}
function dash(){const d=deck(),h=H(),ss=h.sessions,all=d.cards.map((_,i)=>i),st=secStat(all),best=ss.length?Math.max(...ss.map(s=>s.pct)):0,avg=ss.length?Math.round(ss.reduce((a,s)=>a+s.pct,0)/ss.length):0;
const weak=d.cards.map((c,i)=>({c,i,s:h.cardStats[i]})).filter(x=>x.s&&x.s.w>0).sort((a,b)=>(b.s.w-b.s.r)-(a.s.w-a.s.r)).slice(0,6);
app.innerHTML=`<div class="row between" style="margin-bottom:16px"><div><h2 style="margin:0">${esc(d.name)}</h2><span class="muted">${d.cards.length} questions · ${sections().size} sections · ${st.seen} answered at least once</span></div><div class="row"><button class="btn" onclick="fullTest()">Full document test</button><button class="btn ghost" onclick="go('quiz')">Custom quiz</button></div></div>
<div class="grid"><div class="card kpi"><small>Mastery</small><b>${st.mast}%</b><div class="bar"><i style="width:${st.mast}%"></i></div></div>
<div class="card kpi"><small>Coverage</small><b>${Math.round(st.seen/Math.max(d.cards.length,1)*100)}%</b><small>${st.seen} of ${d.cards.length} seen</small></div><div class="card kpi"><small>Quizzes / tests taken</small><b>${ss.length}</b></div><div class="card kpi"><small>Average · Best</small><b>${avg}% · ${best}%</b></div></div>
<div class="card" style="margin-top:16px"><div class="row between"><h3>Sections</h3><span class="muted">Click a section to practice it</span></div><table class="secs">${[...sections()].map(([t,idx],k)=>{const s=secStat(idx);return`<tr><td style="width:46%"><b>${esc(t)}</b><div class="muted">${idx.length} questions${s.acc!==null?` · ${s.acc}% accuracy`:''}</div></td><td><div class="bar"><i style="width:${s.mast}%"></i></div><div class="muted">${s.mast}% mastered</div></td><td style="text-align:right;white-space:nowrap"><button class="btn ghost sm" onclick="secQuiz(${k},'practice')">Practice</button> <button class="btn ghost sm" onclick="secQuiz(${k},'test')">Test</button></td></tr>`}).join('')}</table></div>
<div class="grid" style="margin-top:16px"><div class="card"><h3>Score history</h3>${ss.length?`<div class="chart">${ss.slice(-20).map(s=>`<i title="${s.pct}% · ${s.n} q · ${s.mode}" style="height:${Math.max(s.pct,2)}%"></i>`).join('')}</div><p class="muted">Last ${Math.min(ss.length,20)} sessions</p>`:'<p class="muted">Take a quiz to see your trend.</p>'}</div>
<div class="card"><div class="row between"><h3>Needs practice</h3>${weak.length?`<button class="btn ghost sm" onclick="startQuiz(missedIdx(),'practice')">Review missed</button>`:''}</div>${weak.length?`<table>${weak.map(x=>`<tr><td>${esc(x.c.q)}<div class="muted">${esc(x.c.t||'')}</div></td><td class="muted" style="white-space:nowrap">${x.s.r}✓ ${x.s.w}✗</td></tr>`).join('')}</table>`:'<p class="muted">No missed questions yet.</p>'}</div></div>`}
const missedIdx=()=>Object.entries(H().cardStats).filter(([,s])=>s.w>0).map(([i])=>+i);
function secQuiz(k,mode){const idx=[...sections().values()][k];startQuiz(idx,mode)}
function fullTest(){startQuiz(deck().cards.map((_,i)=>i),'test')}
function quizSetup(){const secs=[...sections()];if(!setup.secs)setup.secs=secs.map(([t])=>t);
app.innerHTML=`<div class="card" style="max-width:820px;margin:0 auto"><h2>Build a quiz or test</h2>
<div class="row between"><h3 style="margin:12px 0 4px">1. Choose sections</h3><div class="row"><button class="btn ghost sm" onclick="setup.secs=[...sections().keys()];quizSetup()">Select all</button><button class="btn ghost sm" onclick="setup.secs=[];quizSetup()">Clear</button></div></div>
<div class="checks">${secs.map(([t,idx])=>`<label class="chk"><input type="checkbox" ${setup.secs.includes(t)?'checked':''} onchange="tog(this,'${esc(t).replace(/'/g,"\\'")}')"> <span>${esc(t)}</span><span class="muted">${idx.length}</span></label>`).join('')}</div>
<h3 style="margin:16px 0 4px">2. Number of questions</h3><div class="row seg">${['10','25','50','100','all'].map(n=>`<button class="${setup.count===n?'on':''}" onclick="setup.count='${n}';quizSetup()">${n==='all'?'All':n}</button>`).join('')}</div>
<h3 style="margin:16px 0 4px">3. Mode</h3><div class="row seg"><button class="${setup.mode==='practice'?'on':''}" onclick="setup.mode='practice';quizSetup()">Practice — instant feedback</button><button class="${setup.mode==='test'?'on':''}" onclick="setup.mode='test';quizSetup()">Test — graded at the end</button></div>
<div class="row between" style="margin-top:20px"><span class="muted" id="pool"></span><button class="btn" id="go" onclick="launch()">Start</button></div></div>`;poolInfo()}
function tog(el,t){setup.secs=el.checked?[...new Set([...setup.secs,t])]:setup.secs.filter(x=>x!==t);poolInfo()}
function pool(){const m=sections();return setup.secs.flatMap(t=>m.get(t)||[])}
function poolInfo(){const n=pool().length,c=setup.count==='all'?n:Math.min(+setup.count,n);$('#pool').textContent=n?`${c} of ${n} available questions from ${setup.secs.length} section${setup.secs.length>1?'s':''}`:'Select at least one section';$('#go').disabled=!n}
function launch(){const p=shuffle(pool());startQuiz(setup.count==='all'?p:p.slice(0,+setup.count),setup.mode,true)}
function startQuiz(idx,mode,preshuffled){nav('quiz');clearInterval(tmr);const d=deck();if(!idx.length){app.innerHTML='<div class="card"><p>No questions to show.</p><button class="btn" onclick="go(\'quiz\')">Back</button></div>';return}
const order=preshuffled?idx:shuffle(idx);Q={idx:order,perm:order.map(i=>shuffle(d.cards[i].o.map((_,k)=>k))),ans:order.map(()=>null),p:0,mode,streak:0,best:0,t0:Date.now()};drawQ()}
function qStats(){let r=0,w=0;Q.ans.forEach((a,j)=>{if(a===null)return;const c=deck().cards[Q.idx[j]];a===c.a?r++:w++});return{r,w}}
function drawQ(){const c=deck().cards[Q.idx[Q.p]],perm=Q.perm[Q.p],pick=Q.ans[Q.p],test=Q.mode==='test',reveal=!test&&pick!==null,{r,w}=qStats(),done=r+w,pct=done?Math.round(r/done*100):0,last=Q.p+1===Q.idx.length;
const opts=perm.map((k,pos)=>{let cls='';if(reveal)cls=k===c.a?'ok':k===pick?'no':'';else if(test&&k===pick)cls='sel';return`<button class="opt ${cls}" ${reveal?'disabled':''} onclick="pick(${k})"><b>${L[pos]}.</b> ${esc(c.o[k])}</button>`}).join('');
app.innerHTML=`<div class="qa"><div class="card"><div class="row between"><span class="tag">${esc(c.t||'General')}</span><span class="muted">${test?'Test':'Practice'} · Question ${Q.p+1} of ${Q.idx.length}</span></div><div class="bar" style="margin:12px 0"><i style="width:${(Q.p+1)/Q.idx.length*100}%"></i></div>
<h2>${esc(c.q)}</h2>${opts}
${reveal?`<div class="fb ${pick===c.a?'ok':'no'}"><b>${pick===c.a?'Correct.':'Not quite — answer: '+esc(c.o[c.a])+'.'}</b> ${esc(c.e||'')}${pg(c)}</div>`:''}
<div class="row between" style="margin-top:14px"><button class="btn ghost" ${Q.p===0||!test?'style="visibility:hidden"':''} onclick="Q.p--;drawQ()">Back</button>${(reveal||test)?`<button class="btn" ${test&&pick===null?'disabled':''} onclick="next()">${last?(test?'Submit test':'See results'):'Next'}</button>`:''}</div></div>
<div class="card score"><h3>Live scorecard</h3>${test?`<div class="kpi"><b>${done}/${Q.idx.length}</b><small>answered — score revealed at the end</small></div><div class="bar" style="margin:10px 0"><i style="width:${done/Q.idx.length*100}%"></i></div>`:`<div class="kpi"><b>${pct}%</b><small>${r} correct · ${w} missed</small></div><div class="bar" style="margin:10px 0"><i style="width:${pct}%"></i></div><p class="muted">Streak: <b>${Q.streak}</b> · Best: <b>${Q.best}</b></p>`}
<p class="muted">Time: <span id="clk">0:00</span></p><button class="btn ghost" onclick="finish()">${test?'Submit now':'End quiz'}</button></div></div>`;tick()}
let tmr;const fmt=s=>`${s/60|0}:${String(s%60).padStart(2,'0')}`;
function tick(){clearInterval(tmr);tmr=setInterval(()=>{const e=$('#clk');if(!e||!Q)return clearInterval(tmr);e.textContent=fmt((Date.now()-Q.t0)/1000|0)},500)}
document.addEventListener('keydown',e=>{if(view!=='quiz'||!Q||e.target.tagName==='INPUT')return;const n='1234'.indexOf(e.key);if(n>=0){const k=Q.perm[Q.p][n];if(k!==undefined)pick(k)}else if(e.key==='Enter'&&Q.ans[Q.p]!==null)next()});
function pick(k){if(Q.mode!=='test'&&Q.ans[Q.p]!==null)return;Q.ans[Q.p]=k;if(Q.mode!=='test'){const c=deck().cards[Q.idx[Q.p]],s=(H().cardStats[Q.idx[Q.p]]??={r:0,w:0});if(k===c.a){Q.streak++;Q.best=Math.max(Q.best,Q.streak);s.r++}else{Q.streak=0;s.w++}}drawQ()}
function next(){if(Q.p+1<Q.idx.length){Q.p++;drawQ()}else finish()}
function finish(){clearInterval(tmr);const d=deck(),secs=new Map();let r=0,n=0;Q.ans.forEach((a,j)=>{if(a===null)return;const i=Q.idx[j],c=d.cards[i],ok=a===c.a;n++;if(ok)r++;if(Q.mode==='test'){const s=(H().cardStats[i]??={r:0,w:0});ok?s.r++:s.w++}const t=c.t||'General';if(!secs.has(t))secs.set(t,{r:0,n:0});secs.get(t).n++;if(ok)secs.get(t).r++});
if(!n){Q=null;go('dash');return}const pct=Math.round(r/n*100),secs_=Math.round((Date.now()-Q.t0)/1000),unans=Q.idx.length-n;H().sessions.push({pct,n,mode:Q.mode,date:Date.now()});
const review=Q.idx.map((i,j)=>({c:d.cards[i],a:Q.ans[j]})).filter(x=>x.a!==null&&x.a!==x.c.a);const R=Q;
app.innerHTML=`<div class="card" style="max-width:820px;margin:0 auto"><div style="text-align:center"><h2>${R.mode==='test'?'Test':'Quiz'} complete</h2><div class="kpi"><b style="font-size:56px">${pct}%</b><small>${r} of ${n} correct${unans?` · ${unans} unanswered`:''} · ${fmt(secs_)}</small></div><p>${pct>=90?'Excellent — close to mastered.':pct>=70?'Solid. Review the missed questions to lock it in.':'Keep going — practice the weaker sections, then retake.'}</p></div>
<h3>Score by section</h3><table>${[...secs].sort((a,b)=>a[1].r/a[1].n-b[1].r/b[1].n).map(([t,v])=>{const p=Math.round(v.r/v.n*100);return`<tr><td>${esc(t)}</td><td style="width:40%"><div class="bar"><i style="width:${p}%;${p<70?'background:var(--bad)':''}"></i></div></td><td class="muted" style="white-space:nowrap">${v.r}/${v.n} · ${p}%</td></tr>`}).join('')}</table>
<div class="row" style="justify-content:center;margin:18px 0"><button class="btn" onclick="startQuiz(${JSON.stringify(R.idx)},'${R.mode}')">Retake</button>${review.length?`<button class="btn ghost" onclick="startQuiz(${JSON.stringify(R.idx.filter((i,j)=>R.ans[j]!==null&&R.ans[j]!==d.cards[i].a))},'practice')">Practice missed (${review.length})</button>`:''}<button class="btn ghost" onclick="go('dash')">Dashboard</button></div>
${review.length?`<h3>Review missed questions</h3>${review.map(x=>`<div class="rev"><b>${esc(x.c.q)}</b><div class="no-t">Your answer: ${esc(x.c.o[x.a])}</div><div class="ok-t">Correct: ${esc(x.c.o[x.c.a])}</div><div class="muted">${esc(x.c.e||'')}${pg(x.c)}</div></div>`).join('')}`:''}</div>`;Q=null}
function flashSetup(){const secs=[...sections()];app.innerHTML=`<div class="card" style="max-width:640px;margin:0 auto"><h2>Flashcards</h2><label>Section</label><select id="fs"><option value="">All sections (${deck().cards.length})</option>${secs.map(([t,idx],k)=>`<option value="${k}">${esc(t)} (${idx.length})</option>`).join('')}</select><div style="margin-top:14px"><button class="btn" onclick="startFlash($('#fs').value)">Start flashcards</button></div></div>`}
function startFlash(k){const d=deck();const idx=k===''?d.cards.map((_,i)=>i):[...sections().values()][+k];if(!idx.length){app.innerHTML='<div class="card">No cards yet.</div>';return}F={o:shuffle(idx),p:0,flip:false,known:0};drawF()}
function drawF(){const c=deck().cards[F.o[F.p]];app.innerHTML=`<div style="max-width:640px;margin:0 auto"><div class="row between"><span class="muted">Card ${F.p+1} of ${F.o.length} · ${esc(c.t||'')}</span><span class="muted">Known: ${F.known}</span></div>
<div class="card flash" style="margin:12px 0" onclick="F.flip=!F.flip;drawF()">${F.flip?`<div><b>${esc(c.o[c.a])}</b><p class="muted" style="font-size:15px">${esc(c.e||'')}${c.p?' (Guide p. '+c.p+')':''}</p></div>`:`<div>${esc(c.q)}<p class="muted" style="font-size:13px">Click to flip</p></div>`}</div>
<div class="row" style="justify-content:center"><button class="btn ghost" onclick="fl(0)">Still learning</button><button class="btn" onclick="fl(1)">I know this</button></div></div>`}
function fl(k){const i=F.o[F.p],s=(H().cardStats[i]??={r:0,w:0});k?(s.r++,F.known++):s.w++;F.p++;F.flip=false;if(F.p<F.o.length)drawF();else app.innerHTML=`<div class="card" style="max-width:520px;margin:40px auto;text-align:center"><h2>Round done</h2><p>You knew ${F.known} of ${F.o.length}.</p><div class="row" style="justify-content:center"><button class="btn" onclick="go('flash')">Again</button><button class="btn ghost" onclick="go('quiz')">Take a quiz</button></div></div>`}
function build(){const d=deck();app.innerHTML=`<div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(320px,1fr))"><div class="card"><h3>New topic</h3><label>Topic name</label><input id="nt" placeholder="e.g. NIST CSF 2.0, Python basics"><div style="margin-top:12px"><button class="btn" onclick="newDeck()">Create topic</button></div>
<h3 style="margin-top:24px">Add a question to “${esc(d.name)}”</h3><label>Question</label><textarea id="fq" rows="2"></textarea>${[0,1,2,3].map(k=>`<label>Option ${L[k]}${k>1?' (optional)':''}</label><input id="fo${k}">`).join('')}
<div class="row"><div style="flex:1"><label>Correct</label><select id="fa"><option value="0">A</option><option value="1">B</option><option value="2">C</option><option value="3">D</option></select></div><div style="flex:1"><label>Section</label><input id="ft" placeholder="General"></div></div><label>Explanation</label><textarea id="fe" rows="2"></textarea><div style="margin-top:12px"><button class="btn" onclick="addQ()">Add question</button></div></div>
<div class="card"><h3>Bulk import</h3><p class="muted">One per line: <code>Question | A | B | C | D | correct letter | explanation | section</code>, or <code>Term :: Definition</code> to auto-build multiple choice.</p><textarea id="bulk" rows="8"></textarea><div class="row" style="margin-top:12px"><button class="btn" onclick="bulk()">Import</button><button class="btn ghost" onclick="exportDeck()">Export JSON</button><label class="btn ghost" style="margin:0">Import JSON<input type="file" accept=".json" hidden onchange="importJSON(this)"></label></div><p id="msg" class="muted"></p>
<h3 style="margin-top:20px">Questions (${d.cards.length})</h3><div style="max-height:420px;overflow:auto"><table>${d.cards.map((c,i)=>`<tr><td>${esc(c.q)}<div class="muted">${esc(c.t||'')}</div></td><td><button class="btn ghost sm" onclick="delQ(${i})">Remove</button></td></tr>`).join('')}</table></div>
<div class="row" style="margin-top:16px"><button class="btn ghost" onclick="resetP()">Reset progress</button>${S.decks.length>1?'<button class="btn ghost" style="border-color:var(--bad);color:var(--bad)" onclick="delDeck()">Delete topic</button>':''}</div></div></div>`}
const msg=t=>{const m=$('#msg');if(m)m.textContent=t};
function newDeck(){const n=$('#nt').value.trim();if(!n)return;const id='d'+Date.now();S.decks.push({id,name:n,cards:[]});S.cur=id;setup.secs=null;go('build')}
function addQ(){const q=$('#fq').value.trim(),o=[0,1,2,3].map(k=>$('#fo'+k).value.trim()).filter(Boolean),a=+$('#fa').value;if(!q||o.length<2||a>=o.length){msg('Need a question, at least two options, and a valid correct answer.');return}deck().cards.push({q,o,a,e:$('#fe').value.trim(),t:$('#ft').value.trim()||'General'});setup.secs=null;build()}
function bulk(){const lines=$('#bulk').value.split('\n').map(l=>l.trim()).filter(Boolean),d=deck();let n=0;const terms=[];
lines.forEach(l=>{if(l.includes('::')){const[t,df]=l.split('::').map(s=>s.trim());if(t&&df)terms.push({t,df})}else{const p=l.split('|').map(s=>s.trim());if(p.length>=4){const Lx=p.findIndex((x,j)=>j>=3&&/^[A-Fa-f]$/.test(x));if(Lx<0)return;const o=p.slice(1,Lx).filter(Boolean),a=L.indexOf(p[Lx].toUpperCase());if(a<o.length){d.cards.push({q:p[0],o,a,e:p[Lx+1]||'',t:p[Lx+2]||'General'});n++}}}});
terms.forEach((x,i)=>{const others=shuffle(terms.filter((_,j)=>j!==i)).slice(0,3).map(y=>y.t);const o=shuffle([x.t,...others]);d.cards.push({q:`Which term matches: “${x.df}”?`,o,a:o.indexOf(x.t),e:`${x.t}: ${x.df}`,t:'Terms'});n++});
setup.secs=null;build();msg(n?`Imported ${n} question${n>1?'s':''}.`:'Nothing imported — check the format.')}
function exportDeck(){const b=new Blob([JSON.stringify({...deck(),progress:H()},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=deck().name.replace(/\W+/g,'-')+'.json';document.body.appendChild(a);a.click();a.remove()}
function importJSON(inp){const f=inp.files[0];if(!f)return;f.text().then(t=>{try{const d=JSON.parse(t);if(!Array.isArray(d.cards))throw 0;const prog=d.progress;delete d.progress;d.id='d'+Date.now();S.decks.push(d);S.cur=d.id;if(prog)S.hist[d.id]=prog;setup.secs=null;go('build');msg('Topic imported.')}catch{msg('That file is not a valid topic export.')}})}
function delQ(i){deck().cards.splice(i,1);H().cardStats={};build()}
function resetP(){S.hist[S.cur]={sessions:[],cardStats:{}};go('dash')}
function delDeck(){S.decks=S.decks.filter(d=>d.id!==S.cur);delete S.hist[S.cur];S.cur=S.decks[0].id;setup.secs=null;go('dash')}

// Review preview: terminology reference and screen navigation.
const DEFINITIONS=[["Analytics", "Analysis of metrics to identify patterns, trends, and information that supports decisions."], ["Assessment objective", "A determination statement describing the desired outcome when assessing a control. All associated assessment objectives must be satisfied."], ["CIAS", "Confidentiality, Integrity, Availability and Safety. The SCRP takes a holistic approach to protecting the Confidentiality, Integrity, Availability and Safety (CIAS) of data, systems and processes."], ["Contractual obligation", "A requirement established by a legal contract between private parties."], ["Control", "A technical, administrative, or physical safeguard that modifies risk."], ["Control objective", "A target or desired condition that a control is intended to achieve."], ["Discretionary Security Requirements (DSR)", "Additional security controls selected to address risk beyond minimum compliance requirements."], ["DPMP", "Data Privacy Management Principles. SCF Data Privacy Management Principles."], ["Due care", "Ongoing actions taken to implement and maintain appropriate safeguards, supported by documented procedures and evidence."], ["Due diligence", "Investigation and planning used to identify requirements, understand risks, and determine appropriate safeguards."], ["ESP", "External Service Provider. Vendors and partners."], ["FUD", "Fear, Uncertainty and Doubt. Unprincipled leaders use FUD to scare business leaders."], ["Guideline", "A recommended practice that allows discretion in how it is interpreted and implemented."], ["HCGF", "Hierarchical Cybersecurity Governance Framework. The HCGF shows how documentation components connect."], ["MADSS", "Mergers, Acquisitions & Divestitures Security Standards. Normalizes MA&D assessment practices."], ["Metric", "A discrete measurement providing a point-in-time view of performance or conditions."], ["Minimum Compliance Requirements (MCR)", "Controls required to satisfy applicable statutory, regulatory, and contractual obligations."], ["Minimum Security Requirements (MSR)", "The resulting control set needed to support both compliance and security."], ["POA&M", "Plan of Action and Milestones: a living record tracking control deficiencies, assigned actions, and remediation progress."], ["Policy", "A high-level statement of executive management intent that explains what the organization expects and why."], ["PPTDF", "People, Processes, Technology, Data and Facilities. The PPTDF(-AI) model looks at People, Processes, Technology, Data and Facilities, plus AI."], ["Procedure", "Documented steps for completing a task in conformance with a standard."], ["Regulatory obligation", "A requirement issued by a government-appointed regulating body."], ["Risk", "Potential exposure to loss or harm. The guide relates risk to control deficiencies and evaluates likelihood and impact."], ["Risk acceptance", "A deliberate decision to retain a risk rather than apply further treatment."], ["Risk avoidance", "Choosing not to undertake an activity that creates an unacceptable risk."], ["Risk reduction", "Applying safeguards or changing activities to reduce likelihood or impact."], ["Risk register", "A record of current risks, including accepted risks and risks with planned mitigation actions."], ["Risk transfer", "Allocating a portion of risk to another party, for example through insurance or contractual arrangements."], ["SCF", "Secure Controls Framework: the control framework referenced throughout the SCRP guide."], ["SCF-B", "The SCF control set purpose-built for mergers, acquisitions, and divestitures due diligence."], ["SCR-CMM", "Secure, Compliant & Resilient Capability Maturity Model: six levels from 0 (Not Performed) through 5 (Continuously Improving)."], ["SCR-CMM 0 \u2014 Not Performed", "Nonexistent practices with no identifiable work products."], ["SCR-CMM 1 \u2014 Performed Informally", "Ad hoc practices dependent on individual effort, with limited consistency and documentation."], ["SCR-CMM 2 \u2014 Planned & Tracked", "Requirements-driven practices supported by planning, tracking, and evidence."], ["SCR-CMM 3 \u2014 Well-Defined", "Practices standardized across the organization."], ["SCR-CMM 4 \u2014 Quantitatively Controlled", "Metrics-driven practices with detailed measures used to understand and predict performance."], ["SCR-CMM 5 \u2014 Continuously Improving", "Practices continuously improved against quantitative goals aligned with business objectives."], ["SCRMS-PIG", "The operational companion to the SCRMS, providing a sequenced, dependency-aware implementation roadmap."], ["SCRP", "Security, Compliance & Resilience Program: a documentation package for organizing cybersecurity and privacy governance."], ["Secure baseline configuration", "A formally reviewed and agreed configuration that provides a secure starting point and is maintained through change control."], ["SEDP", "Secure Engineering & Data Privacy. SEDP principles are common statutory and regulatory expectations."], ["Sensitive Personal Data (sPD)", "Personal data requiring protection throughout its lifecycle under applicable privacy requirements."], ["SSP / SSPP", "A system or project security plan summarizing protection mechanisms and referencing supporting policies, standards, and procedures."], ["Standard", "A mandatory, detailed requirement that implements policy and specifies measurable expectations."], ["Statutory obligation", "A requirement established by a law passed by a state or federal government."], ["TAASD", "Technology Assets, Applications, Services and/or Data. Effective security requires a unified effort by those who interact with Technology Assets, Applications, Services and/or Data (TAASD)."], ["Threat", "A person, event, or condition with the potential to cause damage or danger."]];
const DEFINITION_EXAMPLES={"Analytics": "Compare monthly phishing results to see whether employee reporting improves.", "Assessment objective": "Check configuration evidence to confirm that MFA is enabled for every administrator.", "CIAS": "A robot system protects design files, prevents unauthorized changes, stays available, and operates safely.", "Contractual obligation": "A customer contract requires its supplier to report a security incident within 24 hours.", "Control": "MFA helps prevent a stolen password from being used to access an account.", "Control objective": "Ensure that only authorized employees can access engineering drawings.", "Discretionary Security Requirements (DSR)": "A company adds extra monitoring beyond its contractual minimum because it has a low tolerance for risk.", "DPMP": "A team considers privacy requirements before collecting employee location data.", "Due care": "IT applies approved patches each month and records the results.", "Due diligence": "Before choosing a backup vendor, IT reviews its security controls and recovery capabilities.", "ESP": "A company hires a managed IT provider to maintain its servers.", "FUD": "A salesperson claims a breach is inevitable unless you immediately buy their product.", "Guideline": "Employees are encouraged to use a password manager.", "HCGF": "A policy sets direction, a standard requires MFA, and a procedure explains how to enable it.", "MADSS": "Before acquiring a business, the buyer reviews its security practices and outstanding weaknesses.", "Metric": "This month, 96% of company laptops received required patches.", "Minimum Compliance Requirements (MCR)": "A supplier implements the security controls required by a signed customer agreement.", "Minimum Security Requirements (MSR)": "IT combines required compliance controls with additional controls needed to address business risks.", "POA&M": "An MFA gap is assigned to IT with a target date and milestones for remediation.", "Policy": "Management states that company information must be protected from unauthorized access.", "PPTDF": "A review covers employees, workflows, servers, engineering files, and office access.", "Procedure": "Open the admin console, select the user, and require MFA registration.", "Regulatory obligation": "A regulated business follows reporting requirements issued by its supervising agency.", "Risk": "An unpatched server could be compromised, disrupting production.", "Risk acceptance": "Management documents its decision to tolerate a low-impact risk until a system is retired.", "Risk avoidance": "A team cancels a risky public file-sharing integration.", "Risk reduction": "IT enables MFA to reduce the likelihood of account compromise.", "Risk register": "A tracked entry lists a risk owner, impact, treatment plan, and review date.", "Risk transfer": "A company purchases cyber insurance to transfer part of the financial impact of an incident.", "SCF": "A security team uses SCF controls to organize its access management and incident response reviews.", "SCF-B": "An acquisition team uses SCF-B controls to assess a target company\u2019s security practices.", "SCR-CMM": "A team compares its current practices with a target maturity level and plans improvements.", "SCR-CMM 0 \u2014 Not Performed": "No one performs or documents access reviews.", "SCR-CMM 1 \u2014 Performed Informally": "An administrator reviews access occasionally, using their own method.", "SCR-CMM 2 \u2014 Planned & Tracked": "A team follows a scheduled access review process and keeps evidence.", "SCR-CMM 3 \u2014 Well-Defined": "All departments use the same documented access review process.", "SCR-CMM 4 \u2014 Quantitatively Controlled": "A team measures review completion rates and uses the data to predict delays.", "SCR-CMM 5 \u2014 Continuously Improving": "A team uses performance results to continually improve its review process.", "SCRMS-PIG": "A team establishes foundational governance capabilities before implementing advanced ones.", "SCRP": "A company tailors the SCRP policy and standard templates to its business requirements.", "Secure baseline configuration": "Every new laptop receives an approved configuration with encryption and unnecessary services disabled.", "SEDP": "Engineers plan access restrictions and data minimization before building a new application.", "Sensitive Personal Data (sPD)": "An employee medical record requires tighter access restrictions than a public brochure.", "SSP / SSPP": "A system plan describes its boundaries, owners, safeguards, and supporting procedures.", "Standard": "All privileged accounts must use MFA.", "Statutory obligation": "A business identifies a security requirement in a law that applies to its operations.", "TAASD": "A review inventories servers, applications, hosted services, and the data they process.", "Threat": "A phishing attacker attempts to steal an employee\u2019s sign-in credentials."};
const ACRONYM_NAMES={"CIAS": "Confidentiality, Integrity, Availability and Safety", "DPMP": "Data Privacy Management Principles", "ESP": "External Service Provider", "FUD": "Fear, Uncertainty and Doubt", "HCGF": "Hierarchical Cybersecurity Governance Framework", "MADSS": "Mergers, Acquisitions & Divestitures Security Standards", "POA&M": "Plan of Action and Milestones", "PPTDF": "People, Processes, Technology, Data and Facilities", "SCF": "Secure Controls Framework", "SCF-B": "SCF control set for mergers, acquisitions, and divestitures due diligence", "SCR-CMM": "Secure, Compliant & Resilient Capability Maturity Model", "SCRP": "Security, Compliance & Resilience Program", "SEDP": "Secure Engineering & Data Privacy", "SSP / SSPP": "System Security Plan / System Security & Privacy Plan", "TAASD": "Technology Assets, Applications, Services and/or Data", "SCRMS-PIG": "Security, Compliance & Resilience Management System \u2014 Prioritized Implementation Guide", "SSP": "System Security Plan", "SSPP": "System Security & Privacy Plan", "MCR": "Minimum Compliance Requirements", "DSR": "Discretionary Security Requirements", "MSR": "Minimum Security Requirements", "sPD": "Sensitive Personal Data", "MFA": "Multi-Factor Authentication", "IT": "Information Technology", "HR": "Human Resources", "AO": "Assessment Objective", "AOs": "Assessment Objectives", "SCRMS": "Security, Compliance & Resilience Management System"};
function fullTermName(term){return ACRONYM_NAMES[term]||(term.startsWith('SCR-CMM ')?ACRONYM_NAMES['SCR-CMM']:'')}
function acronymNameHtml(term){const name=fullTermName(term);return name?`<p class="acronym-full-name">${esc(name)}</p>`:''}
function studyText(text){return esc(String(text)).replace(/\b(?:SCRMS-PIG|SCR-CMM|POA&amp;M|CIAS|DPMP|ESP|FUD|HCGF|MADSS|PPTDF|SCF-B|SCF|SCRP|SEDP|SSPP|SSP|TAASD|SCRMS|MCR|DSR|MSR|MFA|AOs|AO|IT|HR|sPD)\b/g,word=>{const key=word.replace('&amp;','&');return ACRONYM_NAMES[key]?`${word} (${esc(ACRONYM_NAMES[key])})`:word})}
const screenTrail=[];
function definitionMatches(c){const text=(c.q+' '+c.o[c.a]+' '+(c.e||'')).toLowerCase();return DEFINITIONS.filter(([term])=>{const variants={'Policy':['policy','policies'],'Standard':['standard','standards'],'Procedure':['procedure','procedures'],'Control':['control','controls'],'Metric':['metric','metrics'],'SSP / SSPP':['ssp','sspp'],'Assessment objective':['assessment objective','assessment objectives','aos']};return(variants[term]||[term.toLowerCase()]).some(t=>new RegExp('\\b'+t.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b','i').test(text))}).slice(0,4)}
function definitionCards(items){return items.map(([term,meaning])=>`<article class="definition-item"><strong>${esc(term)}</strong>${acronymNameHtml(term)}<p>${studyText(meaning)}</p></article>`).join('')}
function referencePanel(c){const items=definitionMatches(c);return items.length?`<aside class="definition-reference"><span class="definition-label">SCRP definition reference</span>${definitionCards(items)}<small class="muted">Study summaries of the SCRP guide terminology.</small></aside>`:''}
const originalDash=dash;dash=function(){originalDash();const firstGrid=app.querySelector('.grid');firstGrid.insertAdjacentHTML('afterend',`<section class="card dashboard-lookup"><div class="row between"><div><span class="definition-label">Study reference</span><h3>Definition lookup</h3></div><button class="btn ghost sm" onclick="go('definitions')">View all ${DEFINITIONS.length} definitions →</button></div><label for="dashboardTerm">Term or acronym</label><input id="dashboardTerm" type="search" placeholder="Type a term, e.g. policy, POA&M, CIAS…" oninput="lookupDefinition(this.value)"><label for="dashboardDefinition">Definition</label><div id="dashboardDefinition" class="lookup-result" role="status" aria-live="polite">Search for a term above to see its definition here.</div></section>`)};
function lookupDefinition(value){const output=$('#dashboardDefinition');if(!value.trim()){output.textContent='Search for a term above to see its definition here.';return}const q=value.toLowerCase().trim();const exact=DEFINITIONS.filter(([t])=>t.toLowerCase()===q);const matches=exact.length?exact:DEFINITIONS.filter(pair=>pair.join(' ').toLowerCase().includes(q)).slice(0,4);output.innerHTML=matches.length?definitionCards(matches):'<p>No matching term. Try another word or browse all definitions.</p>'}
function definitionsPage(){app.innerHTML=`<section class="card definitions"><div class="row between"><div><span class="definition-label">SCRP study library</span><h2>Definitions</h2><p class="muted">Terminology, acronyms, maturity levels, and risk concepts from the study material.</p></div><span class="tag">${DEFINITIONS.length} definitions</span></div><label for="definitionSearch">Find a term or definition</label><input id="definitionSearch" type="search" placeholder="Search terms, acronyms, or meanings…" oninput="filterDefinitions(this.value)"><p class="muted" id="definitionCount">Showing ${DEFINITIONS.length} definitions</p><div id="definitionList" class="definition-grid">${definitionCards(DEFINITIONS)}</div><small class="muted">Study summaries based on the SCRP question bank; consult the guide for exact wording.</small></section>`}
function filterDefinitions(value){const filtered=DEFINITIONS.filter(pair=>pair.join(' ').toLowerCase().includes(value.toLowerCase()));$('#definitionCount').textContent=`Showing ${filtered.length} of ${DEFINITIONS.length} definitions`;$('#definitionList').innerHTML=filtered.length?definitionCards(filtered):'<p class="muted">No matching definitions.</p>'}
const originalDrawQ=drawQ;drawQ=function(){originalDrawQ();if(Q.mode!=='test'&&Q.ans[Q.p]!==null){const target=app.querySelector('.qa > .card');target.insertAdjacentHTML('beforeend',referencePanel(deck().cards[Q.idx[Q.p]]))}};
const originalDrawF=drawF;drawF=function(){
 const c=deck().cards[F.o[F.p]];
 if(c.definitionTerm){
 const meaning=DEFINITIONS.find(([term])=>term===c.definitionTerm)?.[1]||c.e;
 const expansions=ACRONYM_NAMES;
 const expansion=expansions[c.definitionTerm]||(c.definitionTerm.startsWith('SCR-CMM ')?expansions['SCR-CMM']:'');

 app.innerHTML=`<div style="max-width:640px;margin:0 auto"><div class="row between"><span class="tag">Definitions</span><span class="muted">Card ${F.p+1} of ${F.o.length} · Known: ${F.known}</span></div><button class="card flash definition-flash" onclick="F.flip=!F.flip;drawF()" aria-label="Flip definition flashcard"><div><span class="definition-label">${F.flip?'Definition':'Word / term'}</span><h2>${esc(c.definitionTerm)}</h2>${!F.flip&&expansion?`<p class="definition-meaning">${esc(expansion)}</p>`:''}${F.flip?`<p class="definition-meaning">${esc(meaning)}</p><aside class="flash-example"><span class="definition-label">Example</span><p>${studyText(DEFINITION_EXAMPLES[c.definitionTerm]||'')}</p></aside>`:'<p class="muted">Click to reveal the definition</p>'}<span class="muted">${F.flip?'Click to return to the word':'Word → definition'}</span></div></button><div class="row" style="justify-content:center"><button class="btn ghost" onclick="fl(0)">Still learning</button><button class="btn" onclick="fl(1)">I know this</button></div></div>`;
 }else{originalDrawF();if(F.flip)app.insertAdjacentHTML('beforeend',`<div class="flash-reference">${referencePanel(c)}</div>`)}
};
const originalFlashSetup=flashSetup;flashSetup=function(){F=null;originalFlashSetup();app.querySelector('.card').insertAdjacentHTML('afterbegin',`<div class="definition-quiz-shortcut"><span class="definition-label">Word & definition cards</span><h3>Learn the terminology</h3><p class="muted">See the word first. Flip the card to read its definition.</p><button class="btn" onclick="startDefinitionFlashcards()">Study ${DEFINITIONS.length} definitions</button></div>`)};
function startDefinitionFlashcards(){const k=[...sections().keys()].indexOf('Definitions');if(k>=0)startFlash(String(k))}

const originalGo=go;go=function(v){if(view!==v)screenTrail.push(view);Q=null;F=null;originalGo(v)};
function screenBack(){if(view==='quiz'&&Q){if(Q.p>0){Q.p--;drawQ()}else{Q=null;quizSetup()}return}if(view==='flash'&&F){if(F.p>0){F.p--;F.flip=false;drawF()}else flashSetup();return}const target=screenTrail.pop()||'dash';Q=null;F=null;originalGo(target)}
const originalFl=fl;fl=function(k){F.rated??={};const idx=F.o[F.p];if(F.rated[idx]!==undefined){F.p++;F.flip=false;if(F.p<F.o.length)drawF();else{F=null;flashSetup()}return}F.rated[idx]=k;originalFl(k)};

