DEFINITIONS.forEach(([term,meaning],i)=>{
 const alternatives=DEFINITIONS.filter((_,j)=>j!==i);
 const wrong=[alternatives[i%alternatives.length][0],alternatives[(i+13)%alternatives.length][0],alternatives[(i+27)%alternatives.length][0]];
 SEED.cards.push({q:`Which term matches this definition? “${meaning}”`,o:[term,...wrong],a:0,e:`${term}: ${meaning}`,t:'Definitions',definitionTerm:term});
});
const baseQuizSetup=quizSetup;quizSetup=function(){baseQuizSetup();app.querySelector('.card').insertAdjacentHTML('afterbegin',`<div class="definition-quiz-shortcut"><div><span class="definition-label">Terminology practice</span><h3>Quiz yourself on definitions</h3><p class="muted">Match ${DEFINITIONS.length} definitions to their terms, or select Definitions below to combine them with other sections.</p></div><button class="btn" onclick="startDefinitionsQuiz()">Practice definitions</button></div>`)};
function startDefinitionsQuiz(){const indices=deck().cards.map((c,i)=>c.t==='Definitions'?i:null).filter(i=>i!==null);startQuiz(indices,'practice')}


const DEFINITION_SCENARIOS={"Analytics": {"situation": "Compare monthly phishing results to see whether employee reporting improves.", "outcome": "The team notices more employees report suspicious messages after targeted training."}, "Assessment objective": {"situation": "Check configuration evidence to confirm that MFA is enabled for every administrator.", "outcome": "The reviewer checks every privileged account, rather than relying only on the written MFA policy."}, "CIAS": {"situation": "A robot system protects design files, prevents unauthorized changes, stays available, and operates safely.", "outcome": "An outage drill reveals that a safety interlock must keep working even when the main application is unavailable."}, "Contractual obligation": {"situation": "A customer contract requires its supplier to report a security incident within 24 hours.", "outcome": "When a supplier discovers an incident, the manager checks the contract and starts the notification process."}, "Control": {"situation": "MFA helps prevent a stolen password from being used to access an account.", "outcome": "A stolen password fails to give the attacker access because a second authentication factor is required."}, "Control objective": {"situation": "Ensure that only authorized employees can access engineering drawings.", "outcome": "The team removes access from employees whose jobs no longer require the drawings."}, "Discretionary Security Requirements (DSR)": {"situation": "A company adds extra monitoring beyond its contractual minimum because it has a low tolerance for risk.", "outcome": "Leadership approves the additional cost to lower exposure beyond its minimum obligations."}, "DPMP": {"situation": "A team considers privacy requirements before collecting employee location data.", "outcome": "The team decides to collect location only during work activities and limits who can see it."}, "Due care": {"situation": "IT applies approved patches each month and records the results.", "outcome": "When an auditor asks what happened, the team can show the patch records."}, "Due diligence": {"situation": "Before choosing a backup vendor, IT reviews its security controls and recovery capabilities.", "outcome": "The review finds that the vendor cannot meet the required recovery time, so IT evaluates another option."}, "ESP": {"situation": "A company hires a managed IT provider to maintain its servers.", "outcome": "The internal manager still tracks the provider\u2019s responsibilities and performance."}, "FUD": {"situation": "A salesperson claims a breach is inevitable unless you immediately buy their product.", "outcome": "The manager asks for evidence and a risk assessment before approving the purchase."}, "Guideline": {"situation": "Employees are encouraged to use a password manager.", "outcome": "An employee chooses another approved tool because the guidance allows discretion."}, "HCGF": {"situation": "A policy sets direction, a standard requires MFA, and a procedure explains how to enable it.", "outcome": "A new employee can trace the step-by-step instructions back to management\u2019s stated expectations."}, "MADSS": {"situation": "Before acquiring a business, the buyer reviews its security practices and outstanding weaknesses.", "outcome": "The buyer discovers undocumented privileged accounts and asks the seller for a remediation plan."}, "Metric": {"situation": "This month, 96% of company laptops received required patches.", "outcome": "The remaining 4% becomes the focus of the next remediation meeting."}, "Minimum Compliance Requirements (MCR)": {"situation": "A supplier implements the security controls required by a signed customer agreement.", "outcome": "The team records which controls meet each contractual requirement."}, "Minimum Security Requirements (MSR)": {"situation": "IT combines required compliance controls with additional controls needed to address business risks.", "outcome": "The resulting baseline includes both mandatory obligations and the company\u2019s chosen risk treatments."}, "POA&M": {"situation": "An MFA gap is assigned to IT with a target date and milestones for remediation.", "outcome": "At the next review, the owner provides evidence of completed milestones and explains the remaining gap."}, "Policy": {"situation": "Management states that company information must be protected from unauthorized access.", "outcome": "IT writes detailed standards and procedures to put that management direction into practice."}, "PPTDF": {"situation": "A review covers employees, workflows, servers, engineering files, and office access.", "outcome": "The team finds that server controls alone do not address unsecured doors or employee training."}, "Procedure": {"situation": "Open the admin console, select the user, and require MFA registration.", "outcome": "A new technician follows the instructions and completes the task consistently."}, "Regulatory obligation": {"situation": "A regulated business follows reporting requirements issued by its supervising agency.", "outcome": "The compliance lead checks the agency\u2019s specific requirements before deciding what evidence to retain."}, "Risk": {"situation": "An unpatched server could be compromised, disrupting production.", "outcome": "The team evaluates both the chance of compromise and the effect on operations."}, "Risk acceptance": {"situation": "Management documents its decision to tolerate a low-impact risk until a system is retired.", "outcome": "The owner approves the remaining exposure and records an expiration date for that decision."}, "Risk avoidance": {"situation": "A team cancels a risky public file-sharing integration.", "outcome": "The risky activity is removed before company files are uploaded."}, "Risk reduction": {"situation": "IT enables MFA to reduce the likelihood of account compromise.", "outcome": "The team still monitors sign-ins because the safeguard reduces risk rather than eliminating it."}, "Risk register": {"situation": "A tracked entry lists a risk owner, impact, treatment plan, and review date.", "outcome": "The owner updates the entry as remediation progresses so leadership can see the current status."}, "Risk transfer": {"situation": "A company purchases cyber insurance to transfer part of the financial impact of an incident.", "outcome": "IT still has to manage the incident; the insurance covers only the eligible costs in the policy."}, "SCF": {"situation": "A security team uses SCF controls to organize its access management and incident response reviews.", "outcome": "The review reveals that access reviews have an owner but incident response exercises do not."}, "SCF-B": {"situation": "An acquisition team uses SCF-B controls to assess a target company\u2019s security practices.", "outcome": "The buyer uses the assessment findings to discuss remediation effort and acquisition terms."}, "SCR-CMM": {"situation": "A team compares its current practices with a target maturity level and plans improvements.", "outcome": "Leadership chooses a realistic target and funds the capabilities needed to close the gaps."}, "SCR-CMM 0 \u2014 Not Performed": {"situation": "No one performs or documents access reviews.", "outcome": "When a former employee keeps access, the team has no review records to inspect."}, "SCR-CMM 1 \u2014 Performed Informally": {"situation": "An administrator reviews access occasionally, using their own method.", "outcome": "Different administrators reach different conclusions, and no one can demonstrate a consistent process."}, "SCR-CMM 2 \u2014 Planned & Tracked": {"situation": "A team follows a scheduled access review process and keeps evidence.", "outcome": "The manager can show which reviews were scheduled, completed, and tracked."}, "SCR-CMM 3 \u2014 Well-Defined": {"situation": "All departments use the same documented access review process.", "outcome": "A department opening a new office adopts the same approved process as the rest of the business."}, "SCR-CMM 4 \u2014 Quantitatively Controlled": {"situation": "A team measures review completion rates and uses the data to predict delays.", "outcome": "Metrics flag a growing backlog before the next scheduled review is missed."}, "SCR-CMM 5 \u2014 Continuously Improving": {"situation": "A team uses performance results to continually improve its review process.", "outcome": "After analyzing results, the team changes the workflow and measures whether performance improves."}, "SCRMS-PIG": {"situation": "A team establishes foundational governance capabilities before implementing advanced ones.", "outcome": "The team establishes ownership and basic processes before investing in advanced automation."}, "SCRP": {"situation": "A company tailors the SCRP policy and standard templates to its business requirements.", "outcome": "The security engineer removes irrelevant requirements and assigns owners to the applicable ones."}, "Secure baseline configuration": {"situation": "Every new laptop receives an approved configuration with encryption and unnecessary services disabled.", "outcome": "A technician checks the laptop against the baseline before issuing it to an employee."}, "SEDP": {"situation": "Engineers plan access restrictions and data minimization before building a new application.", "outcome": "The design review catches unnecessary data collection before the application launches."}, "Sensitive Personal Data (sPD)": {"situation": "An employee medical record requires tighter access restrictions than a public brochure.", "outcome": "The help desk redirects an access request to the authorized HR owner."}, "SSP / SSPP": {"situation": "A system plan describes its boundaries, owners, safeguards, and supporting procedures.", "outcome": "A new engineer uses the plan to understand the system\u2019s boundaries and the safeguards in place."}, "Standard": {"situation": "All privileged accounts must use MFA.", "outcome": "An administrator cannot treat the MFA requirement as an optional suggestion."}, "Statutory obligation": {"situation": "A business identifies a security requirement in a law that applies to its operations.", "outcome": "The compliance lead confirms applicability instead of assuming every law covers the company."}, "TAASD": {"situation": "A review inventories servers, applications, hosted services, and the data they process.", "outcome": "An overlooked hosted service is added to the inventory and assigned an owner."}, "Threat": {"situation": "A phishing attacker attempts to steal an employee\u2019s sign-in credentials.", "outcome": "The employee reports the message before entering credentials on the fake sign-in page."}};
function scenarioCards(items){return items.map(([term,meaning])=>{const s=DEFINITION_SCENARIOS[term];return `<article class="card scenario-card"><span class="tag">${esc(term)}</span>${acronymNameHtml(term)}<h3>A workplace situation</h3><p>${studyText(s.situation)}</p><p>${studyText(s.outcome)}</p><details><summary>How this illustrates ${esc(term)}</summary><p class="muted">${studyText(meaning)}</p></details></article>`}).join('')}
function scenariosPage(){app.innerHTML=`<section><span class="definition-label">Put the terms into practice</span><h2>Real-World Scenarios</h2><p class="muted">Short, fictional workplace situations for each of the 48 definitions. These are learning examples, not reports of actual events.</p><label for="scenarioSearch">Find a term or situation</label><input id="scenarioSearch" type="search" placeholder="Try policy, MFA, vendor, or risk…" oninput="filterScenarios(this.value)"><p class="muted" id="scenarioCount">Showing ${DEFINITIONS.length} scenarios</p><div class="scenario-grid" id="scenarioList">${scenarioCards(DEFINITIONS)}</div></section>`}
function filterScenarios(value){const q=value.trim().toLowerCase();const items=DEFINITIONS.filter(([term,meaning])=>[term,meaning,DEFINITION_SCENARIOS[term].situation,DEFINITION_SCENARIOS[term].outcome].join(' ').toLowerCase().includes(q));$('#scenarioCount').textContent=`Showing ${items.length} of ${DEFINITIONS.length} scenarios`;$('#scenarioList').innerHTML=items.length?scenarioCards(items):'<p class="muted">No matching scenarios. Try another search.</p>'}

// Spell out known acronyms in study questions and choices.
function plainExpanded(text){return String(text).replace(/\b(?:SCRMS-PIG|SCR-CMM|CIAS|DPMP|ESP|FUD|HCGF|MADSS|PPTDF|SCF-B|SCF|SCRP|SEDP|SSPP|SSP|TAASD|SCRMS|MCR|DSR|MSR|MFA|AOs|AO|IT|HR)\b/g,key=>ACRONYM_NAMES[key]?`${key} (${ACRONYM_NAMES[key]})`:key)}
SEED.cards.forEach(c=>{c.q=plainExpanded(c.q);c.o=c.o.map(plainExpanded)});

// Named browser profiles and resumable quiz sessions.
const PROFILE_STORE='learning-lab-profiles-v1';
const freshStudyState=()=>({decks:[JSON.parse(JSON.stringify(SEED))],cur:'scrp',hist:{}});
let profileStore={version:1,active:null,profiles:{}},activeProfile=null,saveFailure='',pendingProfileAction=null;
try{const raw=localStorage.getItem(PROFILE_STORE);if(raw){const loaded=JSON.parse(raw);if(loaded.version===1&&loaded.profiles&&typeof loaded.profiles==='object')profileStore=loaded;else saveFailure='Saved profiles could not be loaded. Existing browser data has been preserved.'}}catch(e){saveFailure='Browser saving is unavailable. Please allow local storage to keep your progress.'}
function profile(){return activeProfile?profileStore.profiles[activeProfile]:null}
function writeProfiles(){try{localStorage.setItem(PROFILE_STORE,JSON.stringify(profileStore));saveFailure='';return true}catch(e){saveFailure='Progress could not be saved. Browser storage may be full or blocked. Keep this tab open.';return false}}
function captureStudy(){const p=profile();if(!p)return false;p.study=JSON.parse(JSON.stringify(S));p.setup=JSON.parse(JSON.stringify(setup));if(Q){p.pending={deckId:Q.deckId||S.cur,quiz:JSON.parse(JSON.stringify(Q)),elapsed:Math.max(0,Date.now()-Q.t0),savedAt:Date.now()}}p.updatedAt=Date.now();const ok=writeProfiles();updateProfileStatus(ok);return ok}
function updateProfileStatus(ok){const e=$('#profileStatus');if(e)e.textContent=saveFailure||(activeProfile?(ok?'Saved in this browser':'Autosave on'):'Choose your profile');const b=$('#profileButton');if(b)b.textContent=profile()?profile().name+' ▾':'Choose profile'}
function profileDialog(){captureStudy();const p=profile();let dialog=$('#profileDialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='profileDialog';document.body.appendChild(dialog)}dialog.innerHTML=`<form onsubmit="event.preventDefault();createStudyProfile()"><span class="definition-label">Your learning space</span><h2>${p?'Switch profile':'Welcome to Learning Lab'}</h2><p class="muted">Choose a name to keep quiz answers, unfinished tests, and scores in this browser.</p>${Object.keys(profileStore.profiles).length?`<label for="savedProfile">Continue an existing profile</label><select id="savedProfile">${Object.entries(profileStore.profiles).map(([id,p])=>`<option value="${id}" ${id===activeProfile?'selected':''}>${esc(p.name)}</option>`).join('')}</select><button type="button" class="btn" style="margin:12px 0" onclick="selectStudyProfile($('#savedProfile').value)">Continue selected profile</button><hr>`:''}<label for="newProfileName">New profile name</label><input id="newProfileName" maxlength="60" placeholder="Enter your name" autocomplete="off"><p id="profileMessage" class="muted" role="alert"></p><div class="row"><button type="submit" class="btn">Create profile</button>${p?'<button type="button" class="btn ghost" onclick="closeProfileDialog()">Cancel</button>':''}</div><p class="profile-note">Names separate progress; they are not passwords. Anyone using this browser can select a profile. Saves stay on this device and can be erased by clearing browser data.</p>${saveFailure?`<p class="save-warning">${esc(saveFailure)}</p>`:''}</form>`;dialog.oncancel=e=>{if(!activeProfile)e.preventDefault()};if(!dialog.open)dialog.showModal()}
function createStudyProfile(){const input=$('#newProfileName'),name=input.value.trim();if(!name){$('#profileMessage').textContent='Please enter a name.';return}const existing=Object.entries(profileStore.profiles).find(([,p])=>p.name.toLowerCase()===name.toLowerCase());if(existing){$('#profileMessage').textContent='That name already exists. Select it above to continue.';return}const id='p'+Date.now().toString(36)+Math.random().toString(36).slice(2,8);profileStore.profiles[id]={name,study:freshStudyState(),setup:{secs:null,count:'25',mode:'practice'},pending:null,updatedAt:Date.now()};selectStudyProfile(id)}
function selectStudyProfile(id){if(!profileStore.profiles[id])return;if(activeProfile)captureStudy();clearInterval(tmr);Q=null;F=null;activeProfile=id;profileStore.active=id;const p=profile();S=p.study&&Array.isArray(p.study.decks)&&p.study.decks.length?JSON.parse(JSON.stringify(p.study)):freshStudyState();setup=p.setup||{secs:null,count:'25',mode:'practice'};screenTrail.length=0;writeProfiles();const d=$('#profileDialog');if(d&&d.open)d.close();const action=pendingProfileAction;pendingProfileAction=null;if(action)action();else go('dash');updateProfileStatus(true)}
const profileGo=go;go=function(v){if(!activeProfile){pendingProfileAction=()=>go(v);profileDialog();return}captureStudy();profileGo(v);captureStudy()};
const profileDash=dash;dash=function(){profileDash();const p=profile();if(!p)return;const pending=p.pending;const savedDeck=pending&&S.decks.find(d=>d.id===pending.deckId);app.insertAdjacentHTML('afterbegin',`<section class="card profile-dashboard"><div class="row between"><div><span class="definition-label">Your profile</span><h3>Welcome, ${esc(p.name)}</h3><p class="muted">Your scores and progress save automatically in this browser.</p></div><button class="btn ghost sm" onclick="profileDialog()">Switch profile</button></div>${pending&&savedDeck?`<div class="resume-panel"><div><b>Continue your ${pending.quiz.mode==='test'?'test':'practice quiz'}</b><p class="muted">${esc(savedDeck.name)} · Question ${pending.quiz.p+1} of ${pending.quiz.idx.length} · ${pending.quiz.ans.filter(x=>x!==null).length} answered</p><small class="muted">Saved ${new Date(pending.savedAt).toLocaleString()}</small></div><button class="btn" onclick="resumeStudyQuiz()">Resume quiz →</button></div>`:'<p class="muted">No unfinished quiz. Start a quiz to begin.</p>'}${saveFailure?`<p class="save-warning">${esc(saveFailure)}</p>`:''}</section>`)};
function resumeStudyQuiz(){const p=profile(),pending=p&&p.pending;if(!pending)return;const d=S.decks.find(d=>d.id===pending.deckId);if(!d){alert('The saved topic is no longer available.');return}clearInterval(tmr);S.cur=d.id;Q=JSON.parse(JSON.stringify(pending.quiz));Q.t0=Date.now()-(pending.elapsed||0);F=null;nav('quiz');renderSel();drawQ();captureStudy();window.scrollTo(0,0)}
function pauseStudyQuiz(){if(!Q)return;if(captureStudy()){clearInterval(tmr);Q=null;go('dash')}else{drawQ()}}
const profileDrawQ=drawQ;drawQ=function(){profileDrawQ();app.querySelector('.score').insertAdjacentHTML('beforeend',`<button class="btn" style="margin-top:12px;width:100%" onclick="pauseStudyQuiz()">Pause & save</button><p class="profile-note">${esc(profile()?.name||'')} · ${esc(saveFailure||'Answers save automatically')}</p>`)};
const profileStartQuiz=startQuiz;startQuiz=function(idx,mode,preshuffled){if(!activeProfile){pendingProfileAction=()=>startQuiz(idx,mode,preshuffled);profileDialog();return}const old=profile().pending;if(old){if(!confirm('Starting a new quiz replaces your unfinished quiz for this profile. Continue?'))return}profileStartQuiz(idx,mode,preshuffled);if(Q)Q.deckId=S.cur;captureStudy()};
const profilePick=pick;pick=function(k){profilePick(k);captureStudy()};
const profileNext=next;next=function(){profileNext();captureStudy()};
const profileFinish=finish;finish=function(){const p=profile();if(p)p.pending=null;profileFinish();captureStudy()};
const profileScreenBack=screenBack;screenBack=function(){captureStudy();profileScreenBack();captureStudy()};
// Save content changes and flashcard progress as well as quiz answers.
for(const [key,fn] of Object.entries({fl,newDeck,addQ,bulk,delQ,resetP,delDeck})){const wrapped=function(...args){const result=fn(...args);captureStudy();return result};switch(key){case 'fl':fl=wrapped;break;case 'newDeck':newDeck=wrapped;break;case 'addQ':addQ=wrapped;break;case 'bulk':bulk=wrapped;break;case 'delQ':delQ=wrapped;break;case 'resetP':resetP=wrapped;break;case 'delDeck':delDeck=wrapped;break}}
window.addEventListener('pagehide',captureStudy);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')captureStudy()});
setInterval(()=>{if(activeProfile&&Q)captureStudy()},5000);
if(profileStore.active&&profileStore.profiles[profileStore.active])selectStudyProfile(profileStore.active);else{nav('dash');app.innerHTML='<section class="card" style="max-width:680px;margin:30px auto"><h2>Pick up where you left off</h2><p>Choose a name to start saving quiz answers and progress.</p><button class="btn" onclick="profileDialog()">Choose your profile</button></section>';profileDialog()}

function closeProfileDialog(){document.querySelector('#profileDialog').close()}
